c:
$utilities: map-merge(
  $utilities,
  (
    "opacity": null
  )
);

$utilities: map-merge(
  $utilities,
  (
    "cursor": (
      property: cursor,
      class: cursor,
      values: (pointer: pointer, grab: grab)
    )
  )
);

$utilities: map-merge(
  $utilities,
  (
    "display": map-merge(
      map-get($utilities, "display"),
      (responsive: false)
    )
  )
);
